contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // allow receiving ETH refunds from c if any
    receive() external payable {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // To send Ether to c we must hold it here
        require(address(this).balance >= amount);

        // Read the current bet limit so we only attempt wager with the exact required amount
        uint256 beforeBetLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;

        // Only attempt if caller-provided amount equals the contract's bet limit
        require(amount == beforeBetLimit);

        uint256 beforeBalance = address(c).balance;
        bool reverted;

        // Attempt to place the wager of exactly `amount`
        c.wager{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBalance = address(c).balance;
        bool hasWagered = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        // If the call succeeded, contract balance must have increased by amount and the player must be recorded
        // If it reverted, neither effect should be observed
        assert(reverted ? (afterBalance == beforeBalance && !hasWagered) : (afterBalance == beforeBalance + amount && hasWagered));
    }
}

